spec.expr:
sort(
  max by (containerName, hostname, composeProject,containerState) (
    time() - docker_started_time{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
)

(
  sum by (hostname, containerName) (
    docker_memory_usage{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
  / 
  sum by (hostname, containerName) (
    docker_memory_current_limit{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
) * 100

sort_desc(
  max by (hostname, containerName, composeProject, containerState) (
    docker_exit_code{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
)

sort(
  max by (hostname, containerName, composeProject, containerState) (
    docker_memory_inspect_limit{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
)

sort(
  max by (hostname, containerName, composeProject, containerState) (
    docker_container_healthy{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
)

sort_desc(
  max by (hostname, containerName, composeProject, containerState) (
    docker_oom_killed{hostname=~"$Hostname", composeProject=~"$ComposeProject", containerName=~"$ContainerName"}
  )
)
